import {VOICES} from './dialogue-presentation-manifest.js';
import {DialoguePerformance,dialogueAudio} from './dialogue-performance.js';
import {DialoguePortrait} from './dialogue-portrait.js';
import {readSettings,motionPreference} from './settings-3d.js';
import {createDialoguePreferences} from './dialogue-preferences.js';
const $=id=>document.getElementById(id),common='The road is clear. We can go together when you are ready.',lines={guide:'I’m so glad you made it. We did not know about the SAM site, but the radio tower is just up ahead. Did you bring the explosives?',nadia:'Keep back. There is a bomb beside that crate. I need to know you can handle it before I let you near it.',hen:'Your mission is to take out the central relay station.'},actors={guide:{species:'donkey',outfit:'blue-hawaiian'},nadia:{species:'sheep'},hen:{species:'hen'}};
let selected='guide',text=common,serial=0,settings=readSettings(),portrait,player,spans=[],openedAt=0,firstAt=0,samples=[],longTasks=[],cueLags=[],lastCue=null;
const observer=globalThis.PerformanceObserver?new PerformanceObserver(list=>{for(const e of list.getEntries())longTasks.push({at:e.startTime,ms:e.duration});}):null;try{observer?.observe({type:'longtask',buffered:false});}catch{}
function frame(f){if(!firstAt&&f.status==='playing')firstAt=performance.now();for(const s of spans){s.el.style.visibility=!settings.dialogueTextAnimation||f.revealed>s.c0||f.status==='done'||f.status==='fallback'?'visible':'hidden';s.el.style.fontWeight=settings.dialogueTextAnimation&&f.active&&s.c0<f.active.c1&&s.c1>f.active.c0?'750':'400';}
 portrait?.draw(settings.dialoguePortraits==='static'||motionPreference()?.matches||$('blind').checked?0:f.opening);$('state').textContent=f.error||(f.status==='loading'?'Preparing voice…':f.status==='paused'?'Paused. Press Continue.':f.status==='done'?'Line complete.':'');$('resume').hidden=f.status!=='paused';
 const cue=f.active?f.chunk+':'+f.active.c0:null;if(cue&&cue!==lastCue&&f.cueStart!=null)cueLags.push(Math.max(0,(f.clipTime-f.cueStart)*1000));lastCue=cue;
 if(f.status==='playing')samples.push({time:performance.now(),clip:f.clipTime,active:f.active,open:f.opening,cueStart:f.cueStart});samples=samples.slice(-2000);
 $('metrics').textContent=JSON.stringify({browser:navigator.userAgent,viewport:[innerWidth,innerHeight],firstAudioMs:firstAt?Math.round(firstAt-openedAt):null,portrait:portrait?.resources,audio:player?.resources,cueLagP95Ms:cueLags.length?[...cueLags].sort((a,b)=>a-b)[Math.floor((cueLags.length-1)*.95)]:null,longTasks:longTasks.slice(-20)},null,2);
}
function speak(own=false){player?.dispose();settings=readSettings();text=own?lines[selected]:common;$('line').replaceChildren();spans=[];for(const m of text.matchAll(/\S+|\s+/g)){if(/^\s+$/.test(m[0])){$('line').append(document.createTextNode(m[0]));continue;}const wrap=document.createElement('span'),space=document.createElement('strong'),ink=document.createElement('span');wrap.className='dialogue-word';space.className='dialogue-word-space';ink.className='dialogue-word-ink';space.textContent=ink.textContent=m[0];wrap.append(space,ink);$('line').append(wrap);spans.push({el:ink,c0:m.index,c1:m.index+m[0].length});}
 openedAt=performance.now();firstAt=0;cueLags=[];lastCue=null;longTasks=[];player=new DialoguePerformance({context:settings.dialogueVolume>0?dialogueAudio():null,onFrame:frame});player.begin({key:++serial,text,profile:{...VOICES[selected],voice:{...VOICES[selected].voice,...VOICES[selected].language}},settings});
 if(!portrait)portrait=new DialoguePortrait($('face'));portrait.setCharacter(actors[selected]);$('name').textContent=$('blind').checked?'Voice '+(order.indexOf(selected)+1):VOICES[selected].label;
}
const order=['guide','nadia','hen'];for(let i=order.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[order[i],order[j]]=[order[j],order[i]];}
for(const b of document.querySelectorAll('[data-voice]'))b.onclick=()=>{selected=b.dataset.voice;speak();};
$('blind').onchange=()=>{player?.pause();$('face').style.visibility=$('blind').checked?'hidden':'visible';for(const b of document.querySelectorAll('[data-voice]'))b.textContent=$('blind').checked?'Voice '+(order.indexOf(b.dataset.voice)+1):VOICES[b.dataset.voice].label;$('name').textContent='Choose a voice';};
$('neutral').onclick=()=>speak();$('actual').onclick=()=>speak(true);$('skip').onclick=()=>player?.skip();$('replay').onclick=()=>{openedAt=performance.now();firstAt=0;cueLags=[];lastCue=null;longTasks=[];player?.replay(readSettings());};$('resume').onclick=()=>{dialogueAudio();player?.resume();};
const prefs=createDialoguePreferences({onChange:next=>{settings=next;if(player&&next.dialogueVolume>0)player.context=dialogueAudio();player?.settingsChanged(next);}});$('preferences').append(prefs.root);
$('release').onclick=()=>{player?.dispose();portrait?.dispose();$('metrics').textContent=JSON.stringify({released:true,audio:player?.resources,portrait:portrait?.resources},null,2);player=portrait=null;$('name').textContent='Performance closed';$('state').textContent='Choose a voice to open a new performance.';};
$('download').onclick=()=>{const blob=new Blob([JSON.stringify({date:new Date().toISOString(),notes:$('notes').value,voiceOrder:order,metrics:JSON.parse($('metrics').textContent||'{}'),samples},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dialogue-listening-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)player?.pause();});addEventListener('pagehide',()=>{player?.dispose();portrait?.dispose();observer?.disconnect();},{once:true});
